namespace ghidra.app.plugin.core.navigation.locationreferences;

using ghidra.program.model.data;
using ghidra.program.model.data;
using ghidra.program.model.listing;
using ghidra.program.model.listing;
using ghidra.program.util;
using ghidra.util.datastruct;
using ghidra.util.exception;
using ghidra.util.exception;
using ghidra.util.task;

/**
 * A location descriptor to find references to a Union data type.
 */
class UnionLocationDescriptor : DataTypeLocationDescriptor {

	private Union union;

	UnionLocationDescriptor(ProgramLocation location, Program program) : base(location, program)
    {
	}

	/* @Override */
	protected void doGetReferences(Accumulator<LocationReference> accumulator, TaskMonitor monitor)
    {

		// Note: we don't use 'fieldName' of the union, as we have no way of disambiguating which
		//       field a reference will point to. So, grab all references.
		ReferenceUtils.findDataTypeReferences(accumulator, union, program, useDynamicSearching,
			monitor);
	}

	/* @Override */
	protected string generateLabel() {
		return getDataTypeName();
	}

	/* @Override */
	protected DataType getSourceDataType() {
		Data data = getData(getLocation());
		Data parentData = getParent(data);
		DataType dataType = parentData.getDataType();
		if (!(dataType is Union)) {
			throw new AssertException("A Union is required for this LocationDescriptor");
		}
		union = (Union) dataType;
		return dataType;
	}

	private Data getParent(Data data) {
		Data parent = data.getParent();
		if (parent == null) {
			return data;
		}

		Data nextParent = getParent(parent);
		if (nextParent != null) {
			return nextParent;
		}
		return data;
	}

	/* @Override */
	protected string getDataTypeName() {
		return union.getDisplayName();
	}
}
